-- ===== Humane Gang — migration 168 : séries « Pays du monde », « Capitales », « Plateforme de streaming » =====
-- Familles « pays » et « plateforme » ajoutées (image montrée en entière sur fond flouté, comme les pochettes de musique).
-- Les trois séries sont inactives (visibles des admins seulement tant qu'elles ne sont pas ouvertes).
-- Données : feuille HG_Cartes_nouvelles, onglet « Nouvelles collections » (nom, description, rareté selon la popularité).
-- Images : drapeaux (Wikimedia Commons), photos de villes (Wikipédia), logos (TMDB), convertis en .webp dans site/assets/cartes/<série>/.
-- Rejouable : chaque série et ses cartes ne sont créées que si elles n'existent pas.

alter table public.hg_cards drop constraint if exists hg_cards_family_check;
alter table public.hg_cards add constraint hg_cards_family_check
  check (family in ('membre','moment','lieu','objet','evenement','jeu','unique','musique','pays','plateforme'));

insert into public.hg_card_sets (code, name, description, active, sort) values
  ('pays', 'Pays du monde', 'Les 197 pays du monde et leur drapeau.', false, 61),
  ('capitales', 'Capitales', 'Les capitales des 197 pays du monde, en photo.', false, 62),
  ('streaming', 'Plateforme de streaming', 'Les plateformes de streaming vidéo et leurs chaînes, avec leur logo.', false, 63)
on conflict (code) do nothing;


-- Série « pays » : (numéro, nom, rareté, description, légende)
insert into public.hg_cards (set_id, number, name, family, rarity, image_url, flavor, caption)
select s.id, v.n, v.nom, 'pays', v.r, '/assets/cartes/pays/' || lpad(v.n::text, 3, '0') || '.webp', v.descr, v.cap
from public.hg_card_sets s
